// --- Components ---

function formatNum(valor: any, decimales: number = 3) {
  const num = parseFloat(valor);
  if (isNaN(num)) return 0;
  const factor = Math.pow(10, decimales);
  return Math.round(num * factor) / factor;
}

function displayNum(valor: any, decimales: number = 3) {
  const num = formatNum(valor, decimales);
  return formatNumber(num, decimales);
}

const modalDismissStack: Array<() => void> = [];
let modalEscListenerActive = false;

const handleModalEscape = (e: KeyboardEvent) => {
  if (e.key !== 'Escape') return;
  const topDismiss = modalDismissStack[modalDismissStack.length - 1];
  if (topDismiss) {
    e.preventDefault();
    topDismiss();
  }
};

const ensureModalEscListener = () => {
  if (modalEscListenerActive) return;
  modalEscListenerActive = true;
  document.addEventListener('keydown', handleModalEscape);
};

const removeModalEscListenerIfEmpty = () => {
  if (modalDismissStack.length === 0 && modalEscListenerActive) {
    document.removeEventListener('keydown', handleModalEscape);
    modalEscListenerActive = false;
  }
};

function useModalDismiss(onClose: () => void, isOpen: boolean) {
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;

  useEffect(() => {
    if (!isOpen) return;
    const dismiss = () => onCloseRef.current();
    modalDismissStack.push(dismiss);
    ensureModalEscListener();
    return () => {
      const idx = modalDismissStack.lastIndexOf(dismiss);
      if (idx !== -1) modalDismissStack.splice(idx, 1);
      removeModalEscListenerIfEmpty();
    };
  }, [isOpen]);
}

const Modal = ({ isOpen, onClose, title, children, className }: { isOpen: boolean, onClose: () => void, title: string, children: React.ReactNode, className?: string }) => {
  useModalDismiss(onClose, isOpen);
  if (!isOpen) return null;
  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-sleek-dark/60 backdrop-blur-sm p-4"
      onClick={onClose}
    >
      <div
        className={cn("bg-white rounded shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col border-t-8 border-sleek-accent", className)}
        onClick={(e) => e.stopPropagation()}
      >
        <div className={cn("px-8 py-6 border-b border-slate-100 flex justify-between items-center bg-white", className?.includes('modal-egreso') && 'modal-egreso-header')}>
          <h3 className="text-sm font-bold text-sleek-dark uppercase tracking-widest">{title}</h3>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded transition-all text-slate-400 hover:text-sleek-dark">
            <XCircle className="w-5 h-5" />
          </button>
        </div>
        <div className={cn("p-8 overflow-y-auto custom-scrollbar", className?.includes('modal-egreso') && 'modal-egreso-body')}>
          {children}
        </div>
      </div>
    </div>
  );
};

const Card = ({ children, className, onClick }: { children: React.ReactNode, className?: string, onClick?: () => void, key?: any }) => (
  <div 
    onClick={onClick}
    className={cn(
      "bg-white rounded shadow-sm border border-slate-100 overflow-hidden transition-all duration-300", 
      onClick && "cursor-pointer hover:border-sleek-accent hover:shadow-xl hover:-translate-y-1",
      className
    )}
  >
    {children}
  </div>
);

const Badge = ({ children, variant = 'default', className }: { children: React.ReactNode, variant?: 'default' | 'success' | 'warning' | 'danger' | 'info', className?: string }) => {
  const variants = {
    default: 'bg-slate-100 text-slate-700',
    success: 'bg-sleek-success/10 text-sleek-success',
    warning: 'bg-sleek-warning/10 text-sleek-warning',
    danger: 'bg-sleek-danger/10 text-sleek-danger',
    info: 'bg-sky-100 text-sky-700'
  };
  return (
    <span className={cn("px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider", variants[variant], className)}>
      {children}
    </span>
  );
};

const ProgressBar = ({ value, max, label }: { value: number, max: number, label?: string }) => {
  const safeValue = value || 0;
  const safeMax = max || 1;
  const percentage = Math.min(Math.round((safeValue / safeMax) * 100), 100);
  const displayPercentage = isNaN(percentage) ? 0 : percentage;
  let colorClass = 'bg-sleek-success';
  if (displayPercentage > 90) colorClass = 'bg-sleek-danger';
  else if (displayPercentage > 70) colorClass = 'bg-sleek-warning';

  return (
    <div className="w-full">
      <div className="flex justify-between text-[11px] mb-1">
        <span className="font-bold text-slate-500 uppercase">{label}</span>
        <span className="font-bold text-slate-800">{displayPercentage}%</span>
      </div>
      <div className="w-full bg-slate-100 rounded-full h-2 border border-slate-200">
        <div 
          className={cn("h-full rounded-full transition-all duration-500", colorClass)} 
          style={{ width: `${displayPercentage}%` }}
        />
      </div>
    </div>
  );
};

// --- Helper for LocalStorage ---
const loadData = (key: string, initial: any) => {
  if (typeof window === 'undefined') return initial;
  const stored = localStorage.getItem(key);
  return stored ? JSON.parse(stored) : initial;
};

const robustLoadLotesDespiece = (initial: any) => {
  if (typeof window === 'undefined') return initial;
  const posiblesClaves = [
    'alido_lotes_despiece',
    'alido_despiece',
    'alido_lotes_desp',
    'alido_lotesDespiece'
  ];
  
  let todosLosLotes: any[] = [];
  
  for (const clave of posiblesClaves) {
    try {
      const stored = localStorage.getItem(clave);
      if (stored) {
        const datos = JSON.parse(stored);
        if (Array.isArray(datos)) {
          // Normalizar cada lote al cargarlo
          const normalizados = datos.map(l => ({
            ...l,
            id: l.id || l.numeroLote || l.numero || `mig-${Date.now()}-${Math.random()}`,
            numeroLote: l.numeroLote || l.numero || l.id || 'S/N',
            materiaPrimaId: l.materiaPrimaId || l.materiaPrima || l.mpDespostada,
            cantidadIngresada: parseFloat(l.cantidadIngresada || l.cantidad || l.pesoIngresado || 0),
            estado: l.estado || l.status || 'Finalizado',
            fechaElaboracion: l.fechaElaboracion || l.fecha || l.fechaCreacion || new Date().toISOString()
          }));
          todosLosLotes = todosLosLotes.concat(normalizados);
        }
      }
    } catch (e) {
      console.error(`Error cargando clave ${clave}:`, e);
    }
  }
  
  if (todosLosLotes.length === 0) return initial;

  // Eliminar duplicados por ID (o numeroLote si ID es autogenerado)
  const unique = new Map();
  todosLosLotes.forEach(l => {
    // Preferir registros más completos o con IDs establecidos
    const existing = unique.get(l.id);
    if (!existing || (l.estado === 'Finalizado' && existing.estado !== 'Finalizado')) {
      unique.set(l.id, l);
    }
  });
  
  return Array.from(unique.values());
};

const getLoteField = (lote: any, campo: string) => {
  if (!lote) return null;
  const mapeos: Record<string, string[]> = {
    'id': ['id', 'numero', 'loteNumero', 'loteId', 'nroLote'],
    'materia_prima': ['materiaPrimaId', 'materiaPrima', 'mpDespostada', 'producto', 'productoId'],
    'cantidad': ['cantidadIngresada', 'cantidad', 'cantIngresada', 'pesoIngresado'],
    'estado': ['estado', 'status'],
    'fecha': ['fechaElaboracion', 'fecha', 'fechaCreacion'],
    'vencimiento': ['fechaVencimiento', 'vencimiento'],
    'responsable': ['responsableId', 'responsable', 'operario', 'usuario']
  };
  
  const nombres = mapeos[campo] || [campo];
  for (const nombre of nombres) {
    if (lote[nombre] !== undefined && lote[nombre] !== null) {
      return lote[nombre];
    }
  }
  return null;
};

const generarNumeroLote = (
  codigoProducto: string,
  fecha: string,
  lotesExistentes: any[]
): string => {
  const fechaFormateada = (fecha || safeFormat(new Date(), 'yyyy-MM-dd')).replace(/-/g, '');
  const codigo = (codigoProducto || 'SIN').trim();
  const prefijo = `${codigo}-${fechaFormateada}`;
  const lotesDelDia = lotesExistentes.filter((l) => (l.numeroLote || '').startsWith(prefijo));

  let maxCorrelativo = 0;
  lotesDelDia.forEach((l) => {
    const parts = (l.numeroLote || '').split('-');
    const ultimo = parseInt(parts[parts.length - 1], 10);
    if (!isNaN(ultimo) && ultimo > maxCorrelativo) {
      maxCorrelativo = ultimo;
    }
  });

  const correlativo = String(maxCorrelativo + 1).padStart(3, '0');
  return `${prefijo}-${correlativo}`;
};

/** Correlativo numérico del comprobante (último segmento: VTA-20260527-047 → 47). */
const getCorrelativoComprobante = (comprobante: string): number => {
  const parts = (comprobante || '').split('-');
  return parseInt(parts[parts.length - 1], 10) || 0;
};

/** Próximo N° comprobante secuencial (VTA-YYYYMMDD-NNN, EGR-YYYYMMDD-NNN, etc.). */
const generarComprobanteSecuencial = (
  prefijo: string,
  existentes: { id?: string; comprobante?: string }[]
): string => {
  let maxCorrelativo = 0;
  existentes.forEach((item) => {
    const comp = (item.comprobante || item.id || '').trim();
    if (!comp.startsWith(`${prefijo}-`)) return;
    const ultimo = getCorrelativoComprobante(comp);
    if (ultimo > maxCorrelativo) maxCorrelativo = ultimo;
  });
  return `${prefijo}-${String(maxCorrelativo + 1).padStart(3, '0')}`;
};

const generarComprobanteVenta = (
  ventas: { id?: string; comprobante?: string }[],
  fecha?: string | Date
): string => {
  const d =
    fecha instanceof Date
      ? fecha
      : fecha
        ? parseISO(fecha)
        : new Date();
  const prefijo = `VTA-${safeFormat(isValid(d) ? d : new Date(), 'yyyyMMdd')}`;
  return generarComprobanteSecuencial(prefijo, ventas);
};

const generarComprobanteEgreso = (
  egresos: { id?: string; comprobante?: string }[],
  fecha?: string | Date
): string => {
  const d =
    fecha instanceof Date
      ? fecha
      : fecha
        ? parseISO(fecha)
        : new Date();
  const prefijo = `EGR-${safeFormat(isValid(d) ? d : new Date(), 'yyyyMMdd')}`;
  return generarComprobanteSecuencial(prefijo, egresos);
};

/** Recolecta todos los números de lote del sistema para evitar duplicados. */
const collectLotesExistentes = (
  lotesProduccion: any[] = [],
  lotesDespiece: any[] = [],
  movimientos: any[] = []
): { numeroLote: string }[] => {
  const nums = new Set<string>();
  const add = (n?: string) => {
    if (n?.trim()) nums.add(n.trim());
  };
  lotesProduccion.forEach((l) => add(l.numeroLote));
  lotesDespiece.forEach((l) => add(getLoteField(l, 'numeroLote') || l.numeroLote));
  movimientos.forEach((m) => add(m.loteNumero));
  return Array.from(nums).map((numeroLote) => ({ numeroLote }));
};

/** Secuencial del código de barras (último segmento: …-001-001 → 1). */
const extraerSecuencialCodigoBarras = (codigo?: string): number => {
  const c = (codigo || '').trim();
  if (!c) return 0;
  const parts = c.split('-');
  const ultimo = parseInt(parts[parts.length - 1], 10);
  return Number.isNaN(ultimo) ? 0 : ultimo;
};

/** Máximo secuencial usado entre envases (todos los estados: EN STOCK, BAJA, vendido, anulado). */
const maxSecuencialEnvasesList = (envases: any[]): number => {
  let max = 0;
  (envases || []).forEach((e) => {
    const fromCode = extraerSecuencialCodigoBarras(e.codigoBarras || e.codigo);
    if (fromCode > max) max = fromCode;
    const fromNum =
      typeof e.numero === 'number' ? e.numero : parseInt(String(e.numero ?? ''), 10);
    if (!Number.isNaN(fromNum) && fromNum > max) max = fromNum;
  });
  return max;
};

/** Genera el próximo código único; envasesDelLote debe incluir TODOS los envases del lote/sesión (sin filtrar por estado). */
const generarCodigoEnvase = (
  numeroLote: string,
  envasesDelLote: any[],
  esDespiece: boolean = false,
  codigoProductoCorte?: string
): string => {
  if (esDespiece && codigoProductoCorte) {
    const prefijo = `${numeroLote}-${codigoProductoCorte}`;
    const envasesDeEsteCorte = (envasesDelLote || []).filter((e) =>
      codigoEnvasePerteneceALote(e.codigo || e.codigoBarras || '', prefijo)
    );
    const maxNum = maxSecuencialEnvasesList(envasesDeEsteCorte);
    const correlativo = String(maxNum + 1).padStart(3, '0');
    return `${prefijo}-${correlativo}`;
  }

  const maxNum = maxSecuencialEnvasesList(envasesDelLote || []);
  const correlativo = String(maxNum + 1).padStart(3, '0');
  return `${numeroLote}-${correlativo}`;
};

/** Envases del lote para secuencial (todos los estados, uniendo entradas por id interno o número de lote). */
const getEnvasesDelLoteParaSecuencial = (
  loteInternalId: string,
  numeroLote: string,
  lotesEtiquetados: any[],
  esDespiece?: boolean,
  corteKey?: string
): any[] => {
  const entries = lotesEtiquetados.filter((le) => {
    if (esDespiece && corteKey) return le.loteId === corteKey;
    return (
      le.loteId === loteInternalId ||
      le.loteId === numeroLote ||
      (le.loteNumero && le.loteNumero === numeroLote)
    );
  });
  return entries.flatMap((le) => le.envases || []);
};

/** Próximo código único; nunca reutiliza un código ya presente (EN STOCK, BAJA, vendido, etc.). */
const resolveProximoCodigoEnvaseUnico = (
  numeroLote: string,
  envasesDelLote: any[],
  esDespiece = false,
  codigoProductoCorte?: string
): { numero: number; codigoBarras: string } => {
  let codigoBarras = generarCodigoEnvase(numeroLote, envasesDelLote, esDespiece, codigoProductoCorte);
  let numero = extraerSecuencialCodigoBarras(codigoBarras);
  const used = new Set(
    (envasesDelLote || [])
      .map((e) => normalizeEtiquetaCodigo(e.codigoBarras || e.codigo || ''))
      .filter(Boolean)
  );
  let guard = 0;
  while (used.has(normalizeEtiquetaCodigo(codigoBarras)) && guard < 9999) {
    guard += 1;
    numero += 1;
    codigoBarras =
      esDespiece && codigoProductoCorte
        ? `${numeroLote}-${codigoProductoCorte}-${String(numero).padStart(3, '0')}`
        : `${numeroLote}-${String(numero).padStart(3, '0')}`;
  }
  return { numero, codigoBarras };
};

/**
 * Merge inteligente de lotesEtiquetados: combina datos locales y remotos
 * sin perder envases de ninguno de los dos lados.
 */
const mergeLotesEtiquetados = (local: any[], remote: any[]): any[] => {
  const localMap = new Map<string, any>();
  (local || []).forEach((le) => {
    if (le.loteId) localMap.set(le.loteId, le);
  });

  const remoteMap = new Map<string, any>();
  (remote || []).forEach((le) => {
    if (le.loteId) remoteMap.set(le.loteId, le);
  });

  const allLoteIds = new Set([...localMap.keys(), ...remoteMap.keys()]);
  const merged: any[] = [];

  allLoteIds.forEach((loteId) => {
    const localLe = localMap.get(loteId);
    const remoteLe = remoteMap.get(loteId);

    if (!localLe && remoteLe) {
      merged.push(remoteLe);
      return;
    }
    if (localLe && !remoteLe) {
      merged.push(localLe);
      return;
    }

    const localEnvases = localLe.envases || [];
    const remoteEnvases = remoteLe.envases || [];
    const envMap = new Map<string, any>();

    remoteEnvases.forEach((env: any) => {
      const code = normalizeEtiquetaCodigo(env.codigoBarras || env.codigo || '');
      if (code) envMap.set(code, env);
    });

    localEnvases.forEach((env: any) => {
      const code = normalizeEtiquetaCodigo(env.codigoBarras || env.codigo || '');
      if (!code) return;

      const existing = envMap.get(code);
      if (!existing) {
        envMap.set(code, env);
      } else {
        const localTime = new Date(env.fechaBaja || env.fechaHora || '1970-01-01').getTime();
        const remoteTime = new Date(existing.fechaBaja || existing.fechaHora || '1970-01-01').getTime();
        if (localTime > remoteTime) {
          envMap.set(code, env);
        }
      }
    });

    localEnvases.forEach((env: any) => {
      const code = normalizeEtiquetaCodigo(env.codigoBarras || env.codigo || '');
      if (!code) {
        envMap.set(`no-code-${Math.random()}`, env);
      }
    });

    const mergedEnvases = Array.from(envMap.values());
    const pesoTotalEtiquetado = mergedEnvases
      .filter(isEnvaseVigente)
      .reduce((s: number, e: any) => s + (getEnvaseKgDisponibles(e) || 0), 0);

    const baseLe = (new Date(remoteLe.fechaModificacion || remoteLe.fecha || '1970-01-01').getTime() >=
                    new Date(localLe.fechaModificacion || localLe.fecha || '1970-01-01').getTime())
      ? remoteLe
      : localLe;

    merged.push({
      ...baseLe,
      envases: mergedEnvases,
      pesoTotalEtiquetado,
    });
  });

  return merged;
};

/**
 * Une dos arrays de objetos por su campo `id`, sin perder ningún registro.
 * Los registros de `primary` tienen prioridad en caso de conflicto (mismo id).
 * Los registros que solo están en `secondary` se conservan igual.
 * Uso:
 *   - Al guardar: unionById(local, remoto)  → local gana, pero no se pierde nada del remoto
 *   - Al leer:    unionById(remoto, local)  → remoto gana, pero no se pierde nada local
 */
const unionById = (primary: any[], secondary: any[], idKey: string = 'id'): any[] => {
  const map = new Map<string, any>();
  (Array.isArray(secondary) ? secondary : []).forEach((item) => {
    if (item && item[idKey] != null) map.set(String(item[idKey]), item);
  });
  (Array.isArray(primary) ? primary : []).forEach((item) => {
    if (item && item[idKey] != null) map.set(String(item[idKey]), item);
  });
  return Array.from(map.values());
};

// Guarda en Supabase pero ANTES combina con lo que ya hay en la base,
// para no pisar registros que existan remotamente pero no en el estado local.
const persistMerged = async (
  key: string,
  localValue: any[],
  mergeFn: (local: any[], remote: any[]) => any[]
): Promise<void> => {
  try {
    const remote = await loadFromSupabase(key, []);
    const merged = Array.isArray(remote) && remote.length > 0
      ? mergeFn(localValue, remote)
      : localValue;
    await saveToSupabase(key, merged);
    try { localStorage.setItem(key, JSON.stringify(merged)); } catch {}
  } catch {
    // Si falla la lectura remota, guardar el local (mejor eso que perder el guardado)
    await saveToSupabase(key, localValue);
    try { localStorage.setItem(key, JSON.stringify(localValue)); } catch {}
  }
};

/** Número de lote de un corte de despiece: {lotePadre}-{códigoProducto} */
const getNumeroLoteCorteDespiece = (
  numeroLotePadre: string,
  productoId: string,
  productos: any[]
): string => {
  const prod = productos.find((p: any) => p.id === productoId);
  return `${numeroLotePadre}-${prod?.codigo || 'SIN'}`;
};

const corteTieneEnvasesEtiquetados = (
  parentLoteId: string,
  productoId: string,
  lotesEtiquetados: any[]
): boolean => {
  const key = `${parentLoteId}-${productoId}`;
  const le = lotesEtiquetados.find((item: any) => item.loteId === key);
  return !!le?.envases?.some((e: any) => isEnvaseVigente(e));
};

/** Envases vigentes de un corte de despiece por prefijo {lotePadre}-{codigoProducto}. */
const getEnvasesEtiquetasCorteDespiece = (
  numeroLotePadre: string,
  productoId: string,
  productos: any[],
  lotesEtiquetados: any[]
): any[] => {
  const prefijo = getNumeroLoteCorteDespiece(numeroLotePadre, productoId, productos);
  const envases: any[] = [];
  lotesEtiquetados.forEach((le) => {
    (le.envases || []).forEach((e: any) => {
      if (codigoEnvasePerteneceALote(e.codigoBarras || e.codigo || '', prefijo) && isEnvaseVigente(e)) {
        envases.push(e);
      }
    });
  });
  return envases.sort((a, b) => (a.numero || 0) - (b.numero || 0));
};

/** Comprobantes / transacciones: más recientes primero (fecha desc → correlativo desc → id desc). */
const compareRecientesPrimero = (
  a: { fecha?: string; fechaHora?: string; comprobante?: string; fechaCreacion?: string; id?: string },
  b: { fecha?: string; fechaHora?: string; comprobante?: string; fechaCreacion?: string; id?: string }
): number => {
  const fechaA = a.fechaHora || a.fecha || a.fechaCreacion || '';
  const fechaB = b.fechaHora || b.fecha || b.fechaCreacion || '';
  const byFecha = fechaB.localeCompare(fechaA);
  if (byFecha !== 0) return byFecha;
  const byComp =
    getCorrelativoComprobante(b.comprobante || '') - getCorrelativoComprobante(a.comprobante || '');
  if (byComp !== 0) return byComp;
  return (b.id || '').localeCompare(a.id || '');
};

const compareAntiguosPrimero = (
  a: { fecha?: string; fechaHora?: string; comprobante?: string; fechaCreacion?: string; id?: string },
  b: { fecha?: string; fechaHora?: string; comprobante?: string; fechaCreacion?: string; id?: string }
): number => -compareRecientesPrimero(a, b);

/** Más recientes primero: fecha elaboración desc, luego N° lote desc. */
const compareLotesRecientesPrimero = (
  a: { fechaElaboracion?: string; numeroLote?: string; id?: string },
  b: { fechaElaboracion?: string; numeroLote?: string; id?: string }
) => {
  const dateDiff =
    new Date(b.fechaElaboracion || 0).getTime() - new Date(a.fechaElaboracion || 0).getTime();
  if (dateDiff !== 0) return dateDiff;
  const numCmp = (b.numeroLote || '').localeCompare(a.numeroLote || '', undefined, {
    numeric: true,
    sensitivity: 'base',
  });
  if (numCmp !== 0) return numCmp;
  return (b.id || '').localeCompare(a.id || '');
};

const getProductoIdFromLoteProduccion = (l: any): string | undefined => {
  const candidates = [
    l.productoTerminadoId,
    l.productoId,
    l.productoTerminado,
    typeof l.producto === 'object' && l.producto?.id ? l.producto.id : undefined,
    typeof l.producto === 'string' ? l.producto : undefined,
  ];
  return candidates.find((v) => v != null && String(v).trim() !== '') as string | undefined;
};

const getProductoIdFromLoteDespiece = (l: any): string | undefined => {
  const candidates = [
    getLoteField(l, 'materia_prima'),
    l.materiaPrimaId,
    l.materiaPrima,
    l.mpDespostada,
  ];
  return candidates.find((v) => v != null && String(v).trim() !== '') as string | undefined;
};

